#!/usr/bin/env python3
"""Configure the vendored FFmpeg for Horizon (Nintendo Switch, aarch64).

FFmpeg's build configuration is normally produced by its own configure script.
This tree instead carries one committed header per platform, chosen by a
dispatcher, and there was no case for this one.

Rather than keep a large generated header under version control inside a
submodule - which is where it has to live, and which this tree cannot commit to
- that header is derived here from the Android aarch64 configuration. That is
the closest existing target: same architecture, object format, compiler and
NEON support. Only the flags Horizon genuinely differs on are changed, and each
one says why below.

Idempotent. Run it after re-provisioning the FFmpeg submodule:

    python3 thirdparty/ffmpeg-switch/apply.py
"""

import pathlib
import re
import sys

FFMPEG = pathlib.Path(__file__).resolve().parent.parent / "FFmpeg"

# Horizon runs on newlib with libnx rather than bionic.
OVERRIDES = {
    # No POSIX threads. FFmpeg's own threading is not wanted regardless: the
    # guest hands over one XMA frame at a time and the engine decodes it on a
    # thread it already owns.
    "HAVE_PTHREADS": 0,
    "HAVE_THREADS": 0,
    "CONFIG_PTHREADS": 0,
    "HAVE_PTHREAD_CANCEL": 0,
    "HAVE_PTHREAD_SETNAME_NP": 0,
    # Userspace has no virtual memory calls.
    "HAVE_MMAP": 0,
    "HAVE_MPROTECT": 0,
    "HAVE_MUNMAP": 0,
    # No procfs, sysctl or auxv: the CPU count and page size are not
    # discoverable this way, and nothing that is built needs them.
    "HAVE_SYSCONF": 0,
    "HAVE_SYSCTL": 0,
    "HAVE_GETAUXVAL": 0,
    "HAVE_GETRUSAGE": 0,
    "HAVE_SETRLIMIT": 0,
    "HAVE_GETPROCESSMEMORYINFO": 0,
    # No process spawning and no shell globbing.
    "HAVE_FORK": 0,
    "HAVE_GLOB": 0,
    # These newlib does provide.
    "HAVE_UNISTD_H": 1,
    "HAVE_GMTIME_R": 1,
    "HAVE_LOCALTIME_R": 1,
}

BANNER = """/*
 * FFmpeg build configuration for Nintendo Switch (Horizon, aarch64).
 *
 * GENERATED by thirdparty/ffmpeg-switch/apply.py - do not edit by hand.
 * Derived from config_android_aarch64.h; see that script for what differs
 * and why.
 */
"""

DISPATCH = """/* Checked first: devkitA64 defines neither __gnu_linux__ nor __ANDROID__, and
   __SWITCH__ is the only thing that identifies this target. */
#if defined(__SWITCH__)
#if defined(__aarch64__)
#include "config_switch_aarch64.h"
#else
#error "switch arch unsupported"
#endif
#elif defined(WIN32) || defined(_WIN32)"""


def main() -> int:
    source = FFMPEG / "config_android_aarch64.h"
    target = FFMPEG / "config_switch_aarch64.h"
    dispatcher = FFMPEG / "config.h"

    if not source.is_file():
        print(f"missing {source}: is the FFmpeg submodule provisioned?", file=sys.stderr)
        return 1

    text = source.read_text()
    applied, absent = 0, []
    for name, value in OVERRIDES.items():
        pattern = re.compile(r"^#define %s +\d+$" % re.escape(name), re.M)
        text, count = pattern.subn("#define %s %d" % (name, value), text)
        if count:
            applied += 1
        else:
            absent.append(name)
    target.write_text(BANNER + text)
    print(f"wrote {target.name}: {applied} overrides applied")
    if absent:
        print("  not present in this FFmpeg version, skipped: " + ", ".join(absent))

    text = dispatcher.read_text()
    if "config_switch_aarch64.h" in text:
        print(f"{dispatcher.name}: already dispatches for Horizon")
        return 0
    anchor = "#if defined(WIN32) || defined(_WIN32)"
    if anchor not in text:
        print(f"could not find the dispatcher's first branch in {dispatcher}", file=sys.stderr)
        return 1
    dispatcher.write_text(text.replace(anchor, DISPATCH, 1))
    print(f"{dispatcher.name}: added the Horizon branch")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
